import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 19 A very dear cat","description":"学习 have 加宾语加过去分词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 19 A very dear cat","description":"学习 have 加宾语加过去分词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 have 加宾语加过去分词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 18 Electric currents in modern art","link":"/life/english/new-concept/book-3/unit-01/lesson-018"},"next":{"text":"第三册：培养技能 · Lesson 20 Pioneer pilots","link":"/life/english/new-concept/book-3/unit-01/lesson-020"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 18 Electric currents in modern art","link":"/life/english/new-concept/book-3/unit-01/lesson-018"},"next":{"text":"第三册：培养技能 · Lesson 20 Pioneer pilots","link":"/life/english/new-concept/book-3/unit-01/lesson-020"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-01/lesson-019.md","filePath":"life/english/new-concept/book-3/unit-01/lesson-019.md"}'),r={name:"life/english/new-concept/book-3/unit-01/lesson-019.md"};function i(l,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-19-a-very-dear-cat" tabindex="-1">第三册：培养技能 · Lesson 19 A very dear cat <a class="header-anchor" href="#第三册-培养技能-·-lesson-19-a-very-dear-cat" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 19 A very dear cat&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元 1</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从宠物失踪、赎回与情感价值讨论进入被动不定式和使役结构。描述他人的服务或遭遇时，需要分清是主动安排还是不幸承受。学习 have something done 的两种常见意义，避免把所有结构都理解成“让别人做”，并通过上下文判断责任归属。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>ransom</td><td>/ˈrænsəm/</td><td>n.</td><td>赎金</td><td>demand a ransom</td></tr><tr><td>reward</td><td>/rɪˈwɔːd/</td><td>n.</td><td>酬谢</td><td>offer a reward</td></tr><tr><td>valuable</td><td>/ˈvæljuəbl/</td><td>adj.</td><td>贵重的</td><td>a valuable possession</td></tr><tr><td>replace</td><td>/rɪˈpleɪs/</td><td>v.</td><td>替换</td><td>replace a lock</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>put up a notice — 张贴告示</li><li>get in touch with — 与某人取得联系</li></ul><h2 id="语法讲解-have-加宾语加过去分词" tabindex="-1">语法讲解：have 加宾语加过去分词 <a class="header-anchor" href="#语法讲解-have-加宾语加过去分词" aria-label="Permalink to &quot;语法讲解：have 加宾语加过去分词&quot;">​</a></h2><p>have something done 常表示安排别人完成某事，如 have a lock replaced；也可表示遭遇不幸，如 have a bag stolen，不能理解为主动安排偷窃。判断依赖动词和上下文。have someone do something 则让某人执行动作，do 用原形；have someone doing 可强调持续状态。此结构中的时态体现在 have 上，done 随动词采用过去分词。表达动物护理时还要说明实际服务者或目的，避免把语法上的安排误写成已经发生的结果。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>After the gate broke, we had a new lock fitted to keep the dog safely inside.</p></blockquote><p>大门坏后，我们请人安装了新锁，让狗安全地留在里面。</p><p>had 为一般过去时，a new lock 是宾语，fitted 是过去分词补语；to keep 表目的。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>He had his wallet stolen 通常表示钱包被偷的遭遇，不能仅凭 had 就翻译为“他请人偷钱包”。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 had the fence repaired 时把 fence 和 repaired 分清，注意 repaired 的尾音；再对照 had the worker repair，辨别补语形式。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Our puppy escaped through a broken panel. We had the fence repaired that afternoon. A neighbour found the puppy near the bus stop.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句宠物走失后的处理，包含安排服务和最终结果。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>维修安排与找回宠物是两个独立动作，没有暗示维修本身找回了宠物。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：We had the fence ___.（repair/repaired）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> repaired</p><p><strong>解析：</strong> 宾语 fence 承受修理动作。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“让技工检查锁”补完整：We had the technician ___ the lock.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> check</p><p><strong>解析：</strong> have someone do 使用原形。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>例句中谁亲自安装锁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 句子没有说明具体安装者。</p><p><strong>解析：</strong> 结构表示安排安装，不等于主语亲自动手。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：have 加宾语加过去分词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-01/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-01/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-01/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-01/lesson-018">上一课</a> · <a href="/life/english/new-concept/book-3/unit-01/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-01/lesson-020">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
